<?php require_once __DIR__.'/../includes/admin-auth.php';$pageTitle='Reports & analytics';$from=$_GET['from']??'';$to=$_GET['to']??'';if($from!==''&&!v_date($from))$from='';if($to!==''&&!v_date($to))$to='';if($from!==''&&$to!==''&&$from>$to){$t=$from;$from=$to;$to=$t;}$sql="SELECT e.id,e.title,e.event_date,e.capacity,COUNT(DISTINCT CASE WHEN r.status='valid' THEN r.id END) valid_regs,COUNT(DISTINCT c.id) checked FROM events e LEFT JOIN registrations r ON r.event_id=e.id LEFT JOIN checkins c ON c.registration_id=r.id WHERE 1=1";$params=[];if($from){$sql.=' AND e.event_date>=?';$params[]=$from;}if($to){$sql.=' AND e.event_date<=?';$params[]=$to;}$sql.=' GROUP BY e.id ORDER BY e.event_date DESC';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="campuspass-report.csv"');$o=fopen('php://output','w');fputcsv($o,['Event','Date','Capacity','Valid registrations','Checked in','Not checked in','Attendance %','Remaining seats']);foreach($rows as $r){$n=max(0,$r['valid_regs']-$r['checked']);fputcsv($o,[$r['title'],$r['event_date'],$r['capacity'],$r['valid_regs'],$r['checked'],$n,$r['valid_regs']?round($r['checked']/$r['valid_regs']*100,2):0,max(0,$r['capacity']-$r['valid_regs'])]);}fclose($o);exit;} $pageTitle='Reports & analytics';require __DIR__.'/../includes/admin-layout.php'; ?><div class="panel mb-4"><form class="row g-3 align-items-end" data-validate novalidate data-no-lock><div class="col-md-4"><label class="form-label">Event date from</label><input class="form-control" id="from" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-4"><label class="form-label">Event date to</label><input class="form-control" id="to" type="date" name="to" data-after-or-equal="#from" data-msg-after="End date must be on or after the start date." value="<?=e($to)?>"></div><div class="col-md-2 d-grid"><button class="btn btn-primary">Apply</button></div><div class="col-md-2 d-grid"><a class="btn btn-outline-primary" href="?<?=http_build_query(['from'=>$from,'to'=>$to,'export'=>'csv'])?>">Export CSV</a></div></form></div><div class="panel"><h2 class="h5 mb-3">Event attendance overview</h2><div class="table-responsive"><table class="table"><thead><tr><th>Event</th><th>Capacity</th><th>Registrations</th><th>Checked in</th><th>Not checked in</th><th>Attendance</th><th>Seats left</th></tr></thead><tbody><?php foreach($rows as $r):$pct=$r['valid_regs']?round($r['checked']/$r['valid_regs']*100,1):0; ?><tr><td><strong><?=e($r['title'])?></strong><div class="small muted"><?=e(date('M j, Y',strtotime($r['event_date'])))?></div></td><td><?=number_format($r['capacity'])?></td><td><?=number_format($r['valid_regs'])?></td><td><?=number_format($r['checked'])?></td><td><?=number_format(max(0,$r['valid_regs']-$r['checked']))?></td><td><strong><?=$pct?>%</strong><div class="progress mt-1" style="height:6px"><div class="progress-bar" style="width:<?=$pct?>%"></div></div></td><td><?=number_format(max(0,$r['capacity']-$r['valid_regs']))?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="text-center muted">No events found for this date range.</td></tr><?php endif; ?></tbody></table></div><p class="small muted mb-0">Attendance percentage = checked-in participants ÷ valid registrations × 100. Zero registrations are reported as 0%.</p></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
